begin;
alter table public.hh_invites drop constraint if exists hh_invites_role_check;
alter table public.hh_invites add constraint hh_invites_role_check check(role in ('admin','adult','child'));
create or replace function public.hh_join(code uuid) returns void language plpgsql security definer set search_path='' as $$ declare i public.hh_invites%rowtype; begin delete from public.hh_invites v where v.code=$1 and v.expires>now() and v.email=(select lower(u.email) from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null) returning * into i; if not found then raise exception 'Invito non valido'; end if; insert into public.hh_memberships values(i.fid,auth.uid(),i.role) on conflict(fid,uid) do update set role=case when public.hh_memberships.role='admin' or excluded.role='admin' then 'admin' else public.hh_memberships.role end; end $$;
-- Only administrators (parents) control rewards, including through legacy RPCs.
create or replace function public.hh_challenge_manager(f uuid) returns boolean language sql security definer set search_path='' as $$ select exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid() and m.role='admin') $$;
create or replace function public.hh_challenge_grant(f uuid,u uuid,onoff boolean) returns void language plpgsql security definer set search_path='' as $$ begin raise exception 'Usare un invito Genitore'; end $$;
create table if not exists public.hh_proposals(id uuid primary key default gen_random_uuid(),fid uuid not null references public.hh_families on delete cascade,uid uuid not null,kind text not null check(kind in ('task','initiative','prize')),title text not null check(length(trim(title)) between 1 and 200),status text not null default 'pending' check(status in ('pending','approved','rejected')),response text not null default '',created_at timestamptz not null default now(),reviewer uuid,challenge_id uuid references public.hh_challenges(id));
alter table public.hh_proposals enable row level security;
revoke all on public.hh_proposals from public,anon,authenticated;
create or replace function public.hh_proposal_list(f uuid) returns setof public.hh_proposals language sql security definer set search_path='' as $$ select p.* from public.hh_proposals p where p.fid=f and exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) and (p.uid=auth.uid() or public.hh_challenge_manager(f)) order by p.created_at desc $$;
create or replace function public.hh_proposal_add(f uuid,k text,t text) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) then raise exception 'Non autorizzato'; end if; insert into public.hh_proposals(fid,uid,kind,title) values(f,auth.uid(),k,trim(t)); end $$;
create or replace function public.hh_proposal_review(f uuid,i uuid,accept boolean,p integer,d date,n text) returns void language plpgsql security definer set search_path='' as $$ declare r public.hh_proposals; x uuid; begin if not public.hh_challenge_manager(f) then raise exception 'Non autorizzato'; end if; select * into r from public.hh_proposals where fid=f and id=i and status='pending' for update; if not found then raise exception 'Proposta non disponibile'; end if; if accept and r.kind<>'prize' then if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=r.uid) then raise exception 'Familiare non disponibile'; end if; insert into public.hh_challenges(fid,uid,title,due,points,status) values(f,r.uid,r.title,d,p,case when r.kind='initiative' then 'submitted' else 'assigned' end) returning id into x; end if; update public.hh_proposals set status=case when accept then 'approved' else 'rejected' end,response=left(coalesce(n,''),500),reviewer=auth.uid(),challenge_id=x where id=i; end $$;
revoke all on function public.hh_proposal_list(uuid),public.hh_proposal_add(uuid,text,text),public.hh_proposal_review(uuid,uuid,boolean,integer,date,text) from public,anon,authenticated;
grant execute on function public.hh_proposal_list(uuid),public.hh_proposal_add(uuid,text,text),public.hh_proposal_review(uuid,uuid,boolean,integer,date,text) to authenticated;
commit;
